    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('issueInvoice preserves all line data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const issueResult = issueInvoice(invoice, []);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.lines.length, 2);
  assert.deepEqual(issueResult.value.lines[0], invoice.lines[0]);
  assert.deepEqual(issueResult.value.lines[1], invoice.lines[1]);
});

test('issueInvoice does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  const invoice = result.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  issueInvoice(invoice, []);

  assert.deepEqual(invoice, invoiceCopy);
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.number, undefined);
});

test('createInvoice accepts discountPercent on lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
  assert.equal(result.value.lines[1].discountPercent, 0);
});

test('createInvoice returns DISCOUNT_INVALID for invalid discount', () => {
  assert.equal(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 8, discountPercent: -5 }],
    }).error,
    'DISCOUNT_INVALID',
  );

  assert.equal(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 8, discountPercent: 105 }],
    }).error,
    'DISCOUNT_INVALID',
  );

  assert.equal(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 8, discountPercent: 'abc' }],
    }).error,
    'DISCOUNT_INVALID',
  );
});

test('lineDiscount calculates discount amount', () => {
